const CACHE='cobras-lagartos-v7';
const ASSETS=['/','/index.html','/style.css','/app-shell.css','/home-design.css','/app.js','/icon.svg','/manifest.webmanifest','/assets/elenco.jpg','/assets/leona.jpg','/assets/foguinho.jpg','/assets/ellen.jpg','/assets/bel-duda.jpg','/assets/luxus.jpg','/assets/saara.jpg','/assets/home-hero.webp','/assets/home-quiz.webp','/assets/home-record.webp','/assets/icons/house.svg','/assets/icons/book-open.svg','/assets/icons/users.svg','/assets/icons/user.svg','/assets/icons/music-notes.svg','/assets/icons/diamond.svg','/assets/icons/play.svg','/assets/icons/arrow-right.svg','/assets/icons/info.svg','/assets/icons/television.svg'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request).then(response=>response||caches.match('/index.html'))))});
